import{_ as e,o as p,c as t,a3 as o}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/bei-taoyan-de-yongqi/15-苏格拉底和阿德勒.md","filePath":"books/bei-taoyan-de-yongqi/15-苏格拉底和阿德勒.md","lastUpdated":1794748679000}'),_={name:"books/bei-taoyan-de-yongqi/15-苏格拉底和阿德勒.md"};function n(r,a,s,i,d,c){return p(),t("div",null,[...a[0]||(a[0]=[o('<h2 id="苏格拉底和阿德勒" tabindex="-1">苏格拉底和阿德勒 <a class="header-anchor" href="#苏格拉底和阿德勒" aria-label="Permalink to &quot;苏格拉底和阿德勒&quot;">​</a></h2><p>青年：明白了。那么，我再说说另一位朋友的事情。我有位朋友Y是一位非常开朗的男士，即使和陌生人也能谈得来。他深受大家的喜爱，可以瞬间令周围的人展露笑容，简直是一位向日葵般的人。而我就是一个不善与人交往的人，在与他人攀谈的时候总觉得很不自然。那么，先生您按照阿德勒的目的论应该会主张“人可以改变”吧？</p><p>哲人：是的。我也好你也好，人人都可以改变。</p><p>青年：那么先生您认为我可以变成像Y那样的人吗？当然，我是真心地想要变成Y那样的人。</p><p>哲人：如果就目前来讲恐怕比较困难。</p><p>青年：哈哈哈，露出破绽了吧！您是否应该撤回刚才的主张呢？</p><p>哲人：不，并非如此。我不得不遗憾地说，你还没能理解阿德勒心理学。改变的第一步就是理解。</p><p>青年：那您是说只要理解了阿德勒心理学，我也可以变成像Y那样的人？</p><p>哲人：为什么那么急于得到答案呢？答案不应该是从别人那里得到，而应该是自己亲自找出来。从别人那里得到的答案只不过是对症疗法而已，没有什么价值。</p><p>例如，苏格拉底就没有留下一部自己亲手写的著作。将他与雅典的人们，特别是与年轻人的辩论进行整理，然后把其哲学主张写成著作留存后世的是其弟子柏拉图。而阿德勒也是一位毫不关心著述活动，而是热衷于在维也纳的咖啡馆里与人交谈或者是在讨论小组里与人辩论的人物。他们都不是那种只知道闭门造车的知识分子。</p><p>青年：您是说苏格拉底和阿德勒都是想要通过对话来启发人们？</p><p>哲人：正是如此。你心中的种种疑惑都将会在我们接下来的对话中得以解决。而且，你自己也将会有所改变，但那不是通过我的语言而是通过你自己的手。我想通过对话来导出答案，而不是去剥夺你自己发现答案的宝贵过程。也就是说，我们俩要在这个小小的书房内再现苏格拉底或阿德勒那样的对话？</p><p>青年：你不愿意吗？</p><p>哲人：岂会不愿意呢？我非常期待！那就让我们一决胜负吧！</p>',14)])])}const f=e(_,[["render",n]]);export{m as __pageData,f as default};
